"use client";
import { ReactNode, useState } from "react";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faChevronDown } from "@fortawesome/free-solid-svg-icons";

type AccordionItemProps = {
  /** The clickable header content (left of the chevron). */
  header: ReactNode;
  /** The collapsible body content. */
  children: ReactNode;
  /** Whether the item starts open (uncontrolled mode only). */
  defaultOpen?: boolean;
  /** Called the first time the item is opened (lazy-load hook). */
  onFirstOpen?: () => void;
  /** Controlled open state. When provided, the parent owns the state (e.g. single-open accordion). */
  open?: boolean;
  /** Controlled toggle handler. Required when `open` is provided. */
  onToggle?: () => void;
};

/**
 * React-state accordion item that replaces Bootstrap's data-bs-toggle="collapse".
 * Works uncontrolled (own state) or controlled (`open`/`onToggle` from a parent,
 * e.g. to enforce single-open behaviour). Styled to match the new design system
 * (same look as tour-category-page/faq-accordion).
 */
export default function AccordionItem({
  header,
  children,
  defaultOpen = false,
  onFirstOpen,
  open: controlledOpen,
  onToggle,
}: AccordionItemProps) {
  const isControlled = controlledOpen !== undefined;
  const [internalOpen, setInternalOpen] = useState(defaultOpen);
  const [hasOpened, setHasOpened] = useState(defaultOpen);

  const open = isControlled ? controlledOpen : internalOpen;

  const toggle = () => {
    const next = !open;
    if (next && !hasOpened) {
      setHasOpened(true);
      onFirstOpen?.();
    }
    if (isControlled) onToggle?.();
    else setInternalOpen(next);
  };

  return (
    <div
      className={`tw-border-0 tw-border-b tw-border-solid tw-border-[#ece9f1] ${
        open ? "tw-my-1.5" : ""
      }`}
    >
      <button
        type="button"
        onClick={toggle}
        aria-expanded={open}
        className={`tw-flex tw-w-full tw-items-center tw-justify-between tw-gap-4 tw-border-0 tw-px-3 tw-py-4 tw-rounded-lg tw-text-left tw-text-[16px] tw-font-medium tw-transition-colors tw-cursor-pointer ${
          open
            ? "tw-bg-[#f4eefb] tw-text-[#854ec9]"
            : "tw-bg-transparent tw-text-[#14101c] hover:tw-bg-[#faf9fc] hover:tw-text-[#854ec9]"
        }`}
      >
        <span className="tw-flex tw-min-w-0 tw-items-center tw-gap-2">
          {header}
        </span>
        <FontAwesomeIcon
          icon={faChevronDown}
          className={`tw-shrink-0 tw-text-[13px] tw-text-[#854ec9] tw-transition-transform tw-duration-200 ${
            open ? "tw-rotate-180" : ""
          }`}
        />
      </button>
      {/* Smooth height animation via the grid 0fr→1fr trick (content stays in
          the DOM, just clipped). */}
      <div
        className="tw-grid tw-transition-[grid-template-rows] tw-duration-300 tw-ease-out"
        style={{ gridTemplateRows: open ? "1fr" : "0fr" }}
      >
        <div className="tw-overflow-hidden">
          <div className="tw-px-3 tw-pt-2 tw-pb-4">{children}</div>
        </div>
      </div>
    </div>
  );
}
